/* @lc app=leetcode id=2212 lang=kotlin */ class Solution { fun maximumBobPoints(numArrows: Int, aliceArrows: IntArray): IntArray = (0 until 4096).map { mask -> (0 until 12).fold(0 to 0) { acc, i -> if (((mask shr i) and 1) == 1) (acc.first + aliceArrows[i] + 1) to (acc.second + i) else acc }.let { Triple(mask, it.first, it.second) } }.filter { it.second <= numArrows }.maxByOrNull { it.third }!!.let { best -> IntArray(12) { i -> if (((best.first shr i) and 1) == 1) aliceArrows[i] + 1 else 0 }.apply { this[0] += numArrows - best.second } } }